return items.flatMap(item => {
  const data = item.json;

  const values = data.values || [];
  if (values.length < 2) return [];

  const headers = values[0];

  const sheetName = String(data.range || "")
    .split("!")[0]
    .replace(/^'/, "")
    .replace(/'$/, "");

  const nameIndex = headers.indexOf("Название");

  const result = [];

  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    const rowNumber = i + 1;

    const sku = String(row[0] || "").trim();
    const link = String(row[1] || "").trim();
    const photo = String(row[2] || "").trim();
    const title = nameIndex >= 0 ? String(row[nameIndex] || "").trim() : "";

    const first3Filled = sku !== "" && link !== "" && photo !== "";
    const titleEmpty = nameIndex === -1 || title === "";

    if (first3Filled && titleEmpty) {
      result.push({
        json: {
          sheetName,
          rowNumber,
          SKU: sku,
          Ссылка: link,
          Фото: photo,
          headers
        }
      });
    }
  }

  return result;
});

return items.map(item => {
  const row = item.json;

  const sku =
    row.SKU ||
    String(row["Ссылка"]).match(/\/catalog\/(\d+)\//)?.[1];

  const nm = Number(sku);
  const vol = Math.floor(nm / 100000);
  const part = Math.floor(nm / 1000);

  // Надежнее брать basket из ссылки на фото, если она есть
  let basket = null;
  const photo = row["Фото"] || "";
  const m = String(photo).match(/basket-(\d+)\.wbbasket/);
  if (m) basket = m[1].padStart(2, "0");

  if (!basket) {
    throw new Error(`Нет basket в ссылке фото для SKU ${sku}`);
  }

  return {
    json: {
      ...row,
      Артикул: sku,
      cardJsonUrl: `https://basket-${basket}.wbbasket.ru/vol${vol}/part${part}/${nm}/info/ru/card.json`,
    }
  };
});

const BASE_HEADERS = [
  "SKU",
  "Ссылка",
  "Фото",
  "Артикул",
  "Название",
  "Категория 1",
  "Категория 2",
  "Бренд"
];

function val(v) {
  if (Array.isArray(v)) return v.join("; ");
  if (v === null || v === undefined) return "";
  return String(v);
}

function getAllOptions(card) {
  const map = new Map();
  for (const opt of card.options || []) {
    if (opt?.name) map.set(opt.name, val(opt.value));
  }
  for (const group of card.grouped_options || []) {
    for (const opt of group.options || []) {
      if (opt?.name && !map.has(opt.name)) map.set(opt.name, val(opt.value));
    }
  }
  return map;
}

// HTTP Request заменяет item данными ответа card.json, теряя sheetName,
// rowNumber, Фото, headers. Восстанавливаем их из ноды до запроса,
// чтобы merge стал ненужным и данные шли с записью всё время.
const sourceItems = $('Построить URL card.json (строка)').all();

return items.map((item, index) => {
  const card = item.json;
  const src = sourceItems[index]?.json || {};

  const sku = String(
    card.SKU || card["Артикул"] || card.nm_id || card.nmId || src.SKU || ""
  );

  const row = {
    sheetName:     src.sheetName,
    rowNumber:     src.rowNumber,
    headers:       src.headers,

    SKU:           sku,
    Артикул:       sku,
    Ссылка:        src["Ссылка"] || (sku ? `https://www.wildberries.ru/catalog/${sku}/detail.aspx` : ""),
    Фото:          src["Фото"] || "",

    Название:      card.imt_name || card.imtName || card.name || "",
    "Категория 1": card.subj_name || card.subjectName || "",
    "Категория 2": card.subj_root_name || card.parentName || "",
    Бренд:         card.selling?.brand_name || card.brand || card.brand_name || "",
  };

  const optionsMap = getAllOptions(card);
  for (const [name, value] of optionsMap.entries()) {
    if (name === "Фото") continue;
    row[name] = value;
  }

  return { json: row };
});

// Агрегируем все строки в один batchUpdate payload.
// Вместо 50 отдельных PUT-запросов — один POST.
// Если незаполненных строк нет — возвращаем [] чтобы оборвать рекурсию.
const items = $input.all();
if (items.length === 0) return [];

// Пропускаем строки где card.json не вернул данные (Название пустое).
// Они останутся незаполненными и будут перепробованы на следующем прогоне.
const ready = items.filter(item => item.json['Название']);
if (ready.length === 0) return [];

const data = ready.map(item => ({
  range: `'${item.json.sheetName}'!A${item.json.rowNumber}`,
  values: [(item.json.headers || []).map(h => item.json[h] ?? '')]
}));

return [{ json: { batchData: data } }];

const chatId = String($('Start').first().json.chatId || '').trim();
if (!chatId) return [];

return [{
  json: {
    chatId,
    text: '✅ <b>WB Flow</b>: заполнение новых строк завершено'
  }
}];
